        this.barraStato = new BarraStatoAttivita(attivitaService, this::aggiornaDopoCambioStato);
        this.btnSalva = new Button("Salva", evento -> salva());
        this.binder = new Binder<>();
        this.campiPerNome = mappaCampi();
